COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.profile_sk IS 'Customer surrogate key (the governed dimension key).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.profile_id IS 'Durable, pseudonymous customer business key (not raw PII).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.recency_periods IS 'Fiscal periods (NRF 4-5-4) since the customer last purchased.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.frequency IS 'Distinct purchase occasions (orders) in the observation window.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.total_units IS 'Total units purchased.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.total_spend IS 'Total net spend.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.avg_order_value IS 'Average net spend per order (total_spend / frequency).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.historical_clv IS 'Realized gross margin to date; can be negative (a real loss).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.expected_active_periods IS 'Survival heuristic: GREATEST(0, LEAST(tenure, 12) - recency) forward periods.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.predicted_clv IS 'Transparent forward estimate = avg_order_margin x freq_per_period x expected_active_periods; clamped >= 0. Heuristic, not an ML model.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.r_score IS 'Recency score 1-5 from stable fixed thresholds (5 = most recent; reproducible across refreshes, not a population quintile).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.f_score IS 'Frequency score 1-5 from stable fixed thresholds (5 = most frequent).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.m_score IS 'Monetary score 1-5 from stable fixed thresholds (5 = highest spend).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.rfm_score IS 'Combined RFM cell = 100*R + 10*F + M (111..555).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.value_tier IS 'historical_clv tier from stable fixed thresholds (PLATINUM >=2500 / GOLD >=1000 / SILVER >=250 / BRONZE else); reproducible across refreshes, not an NTILE quartile.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_ltv.churn_risk_proxy IS 'Heuristic flag: recency exceeds 2x the typical purchase cadence (tenure / frequency).';

-- ---------- gold_customer_behavioral_attributes (the wide, agent-discoverable trait surface) ----------
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.profile_id IS 'Durable, pseudonymous customer business key (not raw PII) — the single stable activation/join key.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.recency_periods IS 'Fiscal periods since the customer last purchased.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.frequency IS 'Distinct purchase occasions (orders) observed.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.frequency_per_period IS 'Orders per fiscal period of tenure (purchase cadence).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.total_units IS 'Total units purchased.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.total_spend IS 'Total net spend.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.last_order_date IS 'Date of the customer''s most recent order.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.tenure_periods IS 'Fiscal periods from first to latest observed order.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.avg_cadence_periods IS 'The customer''s average purchase cadence: fiscal periods of tenure per order (tenure / frequency). Drives the lifecycle_stage derivation.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.distinct_categories IS 'Count of distinct product categories purchased (breadth of category affinity).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.distinct_brands IS 'Count of distinct brands purchased.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.top_category IS 'The category the customer spends the most net revenue in (dominant category affinity).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.top_brand IS 'The brand the customer spends the most net revenue in.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.promo_purchase_share_ratio IS 'Share of net spend on discounted lines (net < gross) — promo responsiveness, 0..1.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.lifecycle_stage IS 'Behaviorally-derived relationship stage: new / active / lapsing / churned (from recency vs the customer''s own cadence).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.r_score IS 'Recency score 1-5 (from gold_customer_ltv; surfaced as a trait, not recomputed).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.f_score IS 'Frequency score 1-5 (from gold_customer_ltv).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.m_score IS 'Monetary score 1-5 (from gold_customer_ltv).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.rfm_score IS 'Combined RFM cell 111..555 (from gold_customer_ltv).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.value_tier IS 'Value tier PLATINUM/GOLD/SILVER/BRONZE (from gold_customer_ltv).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.historical_clv IS 'Realized lifetime gross margin (from gold_customer_ltv).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.predicted_clv IS 'Heuristic forward CLV estimate (from gold_customer_ltv).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.churn_risk_proxy IS 'Heuristic churn-risk flag (from gold_customer_ltv).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.opt_in_status IS 'Marketing consent as a DISCOVERABLE ATTRIBUTE (opted_in / opted_out / unknown). NOT the legal source of truth (that is canonical-core consent) and never the activation gate — the net gate is applied only in UCV gold_activatable_audience_current.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.interaction_count IS 'Clickstream (ADR 0029), LIFETIME grain (unbounded — NOT the RFM observation window): count of ENGAGEMENT touches for this profile (stitched touches only), excluding session bookkeeping verbs (session_start/session_end/app_open). NULL for a purchaser with no stitched touches.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.session_count IS 'Clickstream, LIFETIME grain (unbounded): distinct sessions (session_id) the profile interacted in.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.last_interaction_date IS 'Clickstream (lifetime scan): most recent touch date (engagement recency).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.avg_digital_dwell_seconds IS 'Clickstream, LIFETIME grain (unbounded): mean page-dwell seconds over DIGITAL engagement touches (web/mobile_app) only. Restricted to one modality because touchpoint.dwell_seconds is cross-modal (page dwell vs call duration vs visit length are not comparable).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.digital_interaction_share IS 'Clickstream channel mix, LIFETIME grain (unbounded — NOT the RFM window; a stale customer''s mix reads like an active one): share of touches on web / mobile_app (0..1). NOTE: the three interaction_share columns are NON-EXHAUSTIVE named shares (direct_mail and other are not bucketed), so they do not sum to 1 — do not treat them as a partition. A touch with a NULL channel_code counts toward the denominator but no named share (harmless on shipped data — the generator always populates channel_code).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.in_store_interaction_share IS 'Clickstream channel mix, LIFETIME grain (unbounded): share of touches in store / kiosk (0..1).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.call_center_interaction_share IS 'Clickstream channel mix, LIFETIME grain (unbounded): share of touches via call center (0..1).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.has_search_intent_flag IS 'Clickstream intent, LIFETIME grain: 1 if the profile had any search touch (ever), else 0.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.has_cart_activity_flag IS 'Clickstream intent, LIFETIME grain: 1 if the profile had any add_to_cart touch (ever), else 0.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.cart_without_checkout_flag IS 'Clickstream, LIFETIME grain: TRUE if the profile ever added to cart but NEVER reached checkout_start across ALL touches. NOTE: checkout_start is reaching checkout, NOT a completed purchase (touchpoint carries no order-completion signal), and this is lifetime not per-cart/session — a habitual buyer who abandoned one old cart still reads FALSE once they checked out. A per-cart/session rate keyed on cart_id/session_id is a follow-on.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.account_id IS 'B2B: durable account key this customer is the PRIMARY CONTACT for. NULL for B2C and for non-primary account members (a full all-contacts roll-up is a follow-up).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.account_type IS 'B2B account type (NULL for B2C).';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.parent_account_id IS 'B2B parent account (account hierarchy), NULL if none.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_customer_behavioral_attributes.computed_ts IS 'When this trait row was computed (freshness).';

