COMMENT ON COLUMN ${catalog}.${acu_schema}.segment_membership.membership_score IS 'Optional confidence/propensity behind the membership (0..1); NULL for a deterministic rule match.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.segment_membership.assignment_method IS 'rule / ml_score / imported.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.segment_membership.model_version IS 'Version of the rule set/model that produced this membership (audit/reproducibility).';

-- ---------- gold_competitive_position (Market Analysis) ----------
COMMENT ON TABLE ${catalog}.${acu_schema}.gold_competitive_position IS 'Category x durable competitor x observed channel x fiscal-period competitive synthesis from independently aggregated price, promotion and assortment observations. It carries no person-level data and never feeds pricing.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.category IS 'Own merchandising category captured by the version-specific price product or source observation.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.competitor_id IS 'Durable competitor business key; aggregation never fragments on the SCD2 surrogate.';
