COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.fiscal_year IS 'NRF 4-5-4 fiscal year.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.fiscal_period IS 'NRF 4-5-4 fiscal period.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.period_start_date IS 'First date in the fiscal period.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.period_end_date IS 'Last date in the fiscal period and SCD2 display-name as-of date.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.currency_code IS 'ISO 4217 reporting currency where monetary observation families agree; NULL on assortment-only rows.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.measure_scope IS 'Reachable observation-family scope: price, promotion, assortment, or promotion_assortment. National price cannot co-occur with source-channel promotion/assortment.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.price_ratio_sum IS 'Additive sum of own list price divided by competitor MRP for usable positive same-currency pairs.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.valid_price_observation_count IS 'Usable positive same-currency regular-price pairs.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.valid_price_product_count IS 'Distinct observed products with at least one usable regular-price pair in this gold grain.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.observed_price_product_count IS 'Distinct matched products present in competitor-price observations.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.price_index_vs_competitor IS 'Unweighted arithmetic mean of usable product-day own-list/competitor-MRP price relatives; 100 is parity.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.sales_weighted_price_ratio_sum IS 'Additive own-list/competitor-MRP ratio multiplied by positive matched own units.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.matched_units IS 'Own units on usable regular-price-pair product-days.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.sales_weighted_price_index_vs_competitor IS 'Own-unit-weighted arithmetic mean of usable product-day own-list/competitor-MRP price relatives; not a ratio of aggregate price totals.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.price_observation_coverage_pct IS '100 x usable price products divided by observed matched price products; no cap is applied.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.competitor_observation_count IS 'Competitor-price observations represented by the row.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.own_promo_presence_count IS 'Own promoted product-days within the shared any-competitor-observation coverage population.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.competitor_promo_presence_count IS 'Competitor promoted product-days within the same observation-coverage population.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.comparable_promo_observation_count IS 'Distinct covered own product-days from price, promotion or assortment observations; SOV denominator population.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.comparable_promo_day_count IS 'Distinct dates represented by the shared promotion-SOV coverage population in this gold grain.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.competitor_promotion_observation_count IS 'All competitor-promotion observations, including category-only placements.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.discount_depth_pct_sum IS 'Additive sum of known competitor-promotion discount depths.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.valid_discount_depth_count IS 'Promotion observations with a known discount depth.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.promo_sov_pct IS '100 x own promoted presence divided by own plus competitor presence on comparable product-days.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.avg_discount_depth_pct IS 'Arithmetic mean of observed or ingest-derived discount-depth percentages over promotion observations with known depth.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.circular_print_promo_count IS 'Observed print-circular promotion placements.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.circular_digital_promo_count IS 'Observed digital-circular promotion placements.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.onsite_promo_count IS 'Observed onsite promotion placements.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.in_store_promo_count IS 'Observed in-store promotion placements.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.email_app_promo_count IS 'Observed email or app promotion placements.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.other_promo_count IS 'Observed promotion placements in other vehicles.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.assortment_observation_count IS 'All competitor listing and availability observations.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.listed_observation_count IS 'Assortment observations explicitly marked listed.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.available_observation_count IS 'Listed assortment observations explicitly marked available.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.out_of_stock_observation_count IS 'Listed assortment observations explicitly marked unavailable.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.stock_flagged_observation_count IS 'Listed assortment observations with known availability state.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.points_of_availability_count IS 'Distinct listed competitor locations in the gold grain; national v1 uses ALL.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.listed_channel_count IS 'Distinct channels with a listed item for the category, competitor and period; repeated on channel rows and non-additive.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.listed_share_pct IS '100 x listed observations divided by all assortment observations.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.availability_rate_pct IS '100 x available listed observations divided by listed observations with known stock state.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.unmatched_listed_item_present_flag IS 'TRUE when match-quality review is needed because a listed competitor item lacks a confidence-qualified exact/equivalent match; not a directional distribution gap.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.competitor_listed_item_count IS 'Distinct listed competitor items in this gold grain.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.matched_listed_product_count IS 'Distinct active own products with exact/equivalent listed competitor matches at confidence 0.80 or higher.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.matched_listed_inactive_product_count IS 'Confidence-qualified listed matches excluded from overlap because the own product is outside the active period-end catalog.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.observed_own_product_count IS 'Distinct active own products represented by at least one assortment observation; overlap/uniqueness denominator.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.matched_listed_competitor_item_count IS 'Distinct listed competitor items with exact/equivalent matches at confidence 0.80 or higher.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.unmatched_listed_item_count IS 'Distinct listed competitor items without a confidence-qualified exact/equivalent match.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.own_catalog_product_count IS 'Distinct active own products in the category at fiscal-period end.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.own_catalog_observation_coverage_pct IS '100 x observed active own products divided by the full active period-end catalog.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.assortment_overlap_pct IS '100 x confidence-qualified active-own matched products divided by observed active own products.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.assortment_uniqueness_pct IS '100 x observed active own products without a confidence-qualified competitor listing divided by observed active own products.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.assortment_jaccard_index_pct IS '100 x matched product-space intersection divided by observed active own products plus unmatched listed competitor items.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.match_coverage_pct IS '100 x confidence-qualified listed competitor items divided by all listed competitor items.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.search_rank_sum IS 'Additive sum of known competitor-item search ranks.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.search_rank_observation_count IS 'Assortment observations with a supplied search rank.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.share_of_search_avg_rank IS 'Search-rank sum divided by ranked observations; not physical shelf share.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.promotion_detection_lag_days_sum IS 'Additive upper-bound days from displayed promotion start to source observation.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.promotion_detection_observation_count IS 'Promotion observations with a computable displayed-start lag.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.avg_promotion_detection_lag_days IS 'Mean displayed-start-to-observation bound for competitor promotions; median is deferred.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.assortment_detection_lag_days_sum IS 'Additive prior-observation intervals where assortment state changed.';
