COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.assortment_state_change_count IS 'Listing or availability changes versus the prior durable-item observation.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.observation_interval_days_sum IS 'Additive days between consecutive assortment observations.';
