COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.avg_observation_cadence_days IS 'Observation-interval day sum divided by interval count.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.price_index_basis IS 'Regular-price basis: own list price versus competitor MRP.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.price_coverage_basis IS 'Usable regular-price products over observed matched price products.';
COMMENT ON COLUMN ${catalog}.${acu_schema}.gold_competitive_position.promo_sov_basis IS 'Promoted product-day presence over own product-days covered by any competitor observation; placement/spend bases are not blended.';
